from flask import Flask, render_template, request, redirect, url_for, session, abort, flash
from datetime import datetime
import json
import os

ROLES = ['administrator', 'teacher', 'office']


def now():
    return datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S UTC')


class Store:
    def __init__(self):
        self.users = {
            'admin': {'password': 'admin', 'roles': ['administrator', 'office']},
            'teacher': {'password': 'teacher', 'roles': ['teacher']},
            'office': {'password': 'office', 'roles': ['office']},
        }
        self.families = []
        self.children = []
        self.invoices = []
        self.audits = []
        self.counter = 1

    def next_id(self, prefix):
        v = f"{prefix}{self.counter}"
        self.counter += 1
        return v


store = Store()


def create_app(test_config=None):
    app = Flask(__name__)
    app.secret_key = 'dev-secret'
    if test_config:
        app.config.update(test_config)

    def current_user():
        name = session.get('user')
        if not name:
            return None
        return {'name': name, **store.users.get(name, {})}

    def login_required(fn):
        from functools import wraps
        @wraps(fn)
        def wrapper(*args, **kwargs):
            if not current_user():
                return redirect(url_for('login'))
            return fn(*args, **kwargs)
        return wrapper

    def role_required(*roles):
        def deco(fn):
            from functools import wraps
            @wraps(fn)
            def wrapper(*args, **kwargs):
                u = current_user()
                if not u or not set(u.get('roles', [])) & set(roles):
                    abort(403)
                return fn(*args, **kwargs)
            return wrapper
        return deco

    def audit(action, record_type, record_id, details=''):
        u = current_user()
        store.audits.append({'time': now(), 'user': u['name'] if u else 'system', 'action': action, 'record_type': record_type, 'record_id': record_id, 'details': details})

    @app.route('/')
    def index():
        return render_template('index.html', user=current_user(), families=store.families, children=store.children, invoices=store.invoices)

    @app.route('/login', methods=['GET', 'POST'])
    def login():
        if request.method == 'POST':
            username = request.form['username']
            password = request.form['password']
            user = store.users.get(username)
            if user and user['password'] == password:
                session['user'] = username
                audit('login', 'user', username)
                return redirect(url_for('index'))
            flash('Invalid login')
        return render_template('login.html')

    @app.route('/logout')
    def logout():
        session.pop('user', None)
        return redirect(url_for('index'))

    @app.route('/families/new', methods=['GET', 'POST'])
    @login_required
    @role_required('administrator', 'office')
    def family_new():
        if request.method == 'POST':
            fam = {'id': store.next_id('F'), 'name': request.form['name'], 'contact': request.form.get('contact', ''), 'status': 'active', 'updated': now()}
            store.families.append(fam)
            audit('create', 'family', fam['id'], fam['name'])
            return redirect(url_for('index'))
        return render_template('family_form.html')

    @app.route('/children/new', methods=['GET', 'POST'])
    @login_required
    @role_required('administrator', 'office')
    def child_new():
        if request.method == 'POST':
            child = {'id': store.next_id('C'), 'name': request.form['name'], 'family': request.form['family'], 'allergies': request.form.get('allergies', ''), 'immunizations': request.form.get('immunizations', ''), 'status': 'draft', 'updated': now()}
            store.children.append(child)
            audit('create', 'child', child['id'], child['name'])
            return redirect(url_for('index'))
        return render_template('child_form.html', families=store.families)

    @app.route('/invoices/new', methods=['GET', 'POST'])
    @login_required
    @role_required('administrator', 'office')
    def invoice_new():
        if request.method == 'POST':
            inv = {'id': store.next_id('I'), 'family': request.form['family'], 'amount': float(request.form['amount']), 'paid': 0.0, 'status': 'submitted', 'history': []}
            store.invoices.append(inv)
            audit('create', 'invoice', inv['id'], str(inv['amount']))
            return redirect(url_for('index'))
        return render_template('invoice_form.html', families=store.families)

    @app.route('/invoices/<iid>/pay', methods=['POST'])
    @login_required
    @role_required('administrator', 'office')
    def invoice_pay(iid):
        inv = next((i for i in store.invoices if i['id'] == iid), None)
        if not inv:
            abort(404)
        amt = float(request.form['amount'])
        inv['paid'] += amt
        inv['history'].append({'time': now(), 'amount': amt})
        inv['status'] = 'paid' if inv['paid'] >= inv['amount'] else 'partial'
        audit('payment', 'invoice', iid, str(amt))
        return redirect(url_for('index'))

    @app.route('/export/invoices')
    @login_required
    @role_required('administrator', 'office')
    def export_invoices():
        return app.response_class(json.dumps(store.invoices, indent=2), mimetype='application/json')

    @app.route('/audit')
    @login_required
    def audit_view():
        return render_template('audit.html', audits=reversed(store.audits))

    @app.route('/seed-demo')
    def seed_demo():
        if not store.families:
            store.families.append({'id': store.next_id('F'), 'name': 'Nguyen Family', 'contact': 'parent@example.com', 'status': 'active', 'updated': now()})
        return redirect(url_for('index'))

    return app
EOF

